mapper.select:
SELECT audit_id, admin_id, target_table, target_pk, before_value, after_value, reason_code, processed_at
FROM audit_log


        AND admin_id = #{adminId}


        AND target_table = #{targetTable}


        AND target_pk = #{targetPk}


        AND reason_code = #{reasonCode}


        AND processed_at >= #{startDate}


        AND processed_at <= #{endDate}


ORDER BY processed_at DESC
